import React, { useState, useEffect } from "react";
import "../Styles/UserProfile.css";

const CompanyProfile = () => {
  const [company, setCompany] = useState(null);
  const [payment, setPayment] = useState(null);
  const [showEditInfo, setShowEditInfo] = useState(false);
  const [showEditPayment, setShowEditPayment] = useState(false);

  const [stats, setStats] = useState({ jobsPosted: 0, messages: 0 });

  useEffect(() => {
    const storedCompany = JSON.parse(localStorage.getItem("companyData"));
    if (storedCompany) setCompany(storedCompany);

    const storedPayment = JSON.parse(localStorage.getItem("companyPayment"));
    if (storedPayment) setPayment(storedPayment);

    const postedJobs = JSON.parse(localStorage.getItem("postedJobs")) || [];
    setStats({
      jobsPosted: postedJobs.filter(
        (j) => j.company === storedCompany?.companyName
      ).length,
      messages: 0, // placeholder
    });
  }, []);

  const handleSaveInfo = (e) => {
    e.preventDefault();
    localStorage.setItem("companyData", JSON.stringify(company));
    setShowEditInfo(false);
    alert("Company info updated ✅");
  };

  const handleSavePayment = (e) => {
    e.preventDefault();
    localStorage.setItem("companyPayment", JSON.stringify(payment));
    setShowEditPayment(false);
    alert("Payment details saved ✅");
  };

  const handleDeletePayment = () => {
    localStorage.removeItem("companyPayment");
    setPayment(null);
    alert("Payment deleted 🗑️");
  };

  if (!company)
    return <p style={{ textAlign: "center" }}>Loading company data...</p>;

  return (
    <div className="profile-page">
      {/* ----- Company Info ----- */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-icon">🏢</div>
          <div>
            <h2 className="profile-name">{company.companyName}</h2>
            <p className="profile-email">{company.email}</p>
            <p className="profile-detail">
              {company.industry} • {company.location}
            </p>
          </div>
        </div>
        <button className="update-btn" onClick={() => setShowEditInfo(true)}>
          Update your Info
        </button>
      </div>

      {/* ----- Activity ----- */}
      <div className="history-box">
        <h3>Recent activity</h3>
        <ul>
          <li>Jobs posted: {stats.jobsPosted}</li>
          <li>Messages received: {stats.messages}</li>
        </ul>
      </div>

      {/* ----- Payment Details ----- */}
      <div className="payment-box">
        <h3>Payment details</h3>
        {!payment ? (
          <div>
            <p>No payment info yet.</p>
            <button
              className="add-btn"
              onClick={() => setShowEditPayment(true)}
            >
              ➕ Add your Payment
            </button>
          </div>
        ) : (
          <div className="payment-info">
            <p>🏦 Bank Name: {payment.bankName}</p>
            <p>💳 Account Number: ******{payment.accountNumber.slice(-4)}</p>
            <div className="payment-actions">
              <button
                className="update-btn small"
                onClick={() => setShowEditPayment(true)}
              >
                ✏️ Edit Payment
              </button>
              <button
                className="delete-btn small"
                onClick={handleDeletePayment}
              >
                🗑️ Delete
              </button>
            </div>
          </div>
        )}
      </div>

      {/* ----- Modal: Edit Info ----- */}
      {showEditInfo && (
        <div className="modal-overlay">
          <div className="modal-content small">
            <h3>Edit Company Info</h3>
            <form onSubmit={handleSaveInfo}>
              <label>Company Name</label>
              <input
                type="text"
                value={company.companyName}
                onChange={(e) =>
                  setCompany({ ...company, companyName: e.target.value })
                }
                required
              />
              <label>Email</label>
              <input
                type="email"
                value={company.email}
                onChange={(e) =>
                  setCompany({ ...company, email: e.target.value })
                }
                required
              />
              <label>Industry Type</label>
              <input
                type="text"
                value={company.industry}
                onChange={(e) =>
                  setCompany({ ...company, industry: e.target.value })
                }
              />
              <label>Location</label>
              <input
                type="text"
                value={company.location}
                onChange={(e) =>
                  setCompany({ ...company, location: e.target.value })
                }
              />
              <div className="modal-btns">
                <button type="submit" className="save-btn">
                  Save
                </button>
                <button
                  type="button"
                  className="cancel-btn"
                  onClick={() => setShowEditInfo(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ----- Modal: Payment ----- */}
      {showEditPayment && (
        <div className="modal-overlay">
          <div className="modal-content small">
            <h3>💳 {payment ? "Edit Payment Info" : "Add Your Payment"}</h3>
            <form onSubmit={handleSavePayment}>
              <label>Bank Name</label>
              <select
                value={payment?.bankName || ""}
                onChange={(e) =>
                  setPayment({ ...payment, bankName: e.target.value })
                }
                required
              >
                <option value="">Select your bank</option>
                <option value="Bank Muscat">Bank Muscat</option>
                <option value="Bank Dhofar">Bank Dhofar</option>
                <option value="National Bank of Oman">
                  National Bank of Oman
                </option>
              </select>

              <label>Account Number</label>
              <input
                type="text"
                value={payment?.accountNumber || ""}
                onChange={(e) =>
                  setPayment({ ...payment, accountNumber: e.target.value })
                }
                required
              />
              <div className="modal-btns">
                <button type="submit" className="save-btn">
                  Save
                </button>
                <button
                  type="button"
                  className="cancel-btn"
                  onClick={() => setShowEditPayment(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyProfile;
